#!/usr/bin/env python3
from pathlib import Path
import re, sys

root=Path(sys.argv[1] if len(sys.argv)>1 else "game")
script=root/"scripts"/"art"/"d2d29_minimal_token_runtime.gd"
if not script.exists():
    raise SystemExit("D2D.63 requires D2D.62 runtime")

s=script.read_text(encoding="utf-8")
if 'title.text = "D2D.62 FEMALE PROPORTION FIX:"' not in s:
    raise SystemExit("D2D.63 title anchor missing")
s=s.replace('title.text = "D2D.62 FEMALE PROPORTION FIX:"',
            'title.text = "D2D.63 FEMALE HEAD ONLY:"',1)

# Head-only build: body, torso, legs, backpack, boots and gloves are untouched.
s,n=re.subn(r'const FEMALE_HEAD_B64 := "[^"]+"',
            'const FEMALE_HEAD_B64 := "[... ELLIPSIZATION ...]"',s,count=1)
if n!=1:
    raise SystemExit("D2D.63 female head constant missing")

# Reload the exact user-provided female head and force the female branch to use it.
if 'tex_head_female = _texture_from_embedded_png(FEMALE_HEAD_B64)' not in s:
    raise SystemExit("D2D.63 female head loader missing")

old='''        if female_mode and tex_head_female != null:
            draw_texture_rect(tex_head_female, Rect2(Vector2(-8.45,-17.15), Vector2(16.9,18.4)), false)
        else:
            draw_texture_rect(tex_head_right, Rect2(Vector2(-8.45,-17.15), Vector2(16.9,18.4)), false)
'''
new='''        if female_mode:
            # D2D.63: exact supplied female profile, same envelope/pivot as the male head.
            draw_texture_rect(tex_head_female, Rect2(Vector2(-8.45,-17.15), Vector2(16.9,18.4)), false)
        else:
            draw_texture_rect(tex_head_right, Rect2(Vector2(-8.45,-17.15), Vector2(16.9,18.4)), false)
'''
if old not in s:
    raise SystemExit("D2D.63 female head draw anchor missing")
s=s.replace(old,new,1)

script.write_text(s,encoding="utf-8")

ep=root/"export_presets.cfg"
e=ep.read_text(encoding="utf-8")
e,n1=re.subn(r'(?m)^version/code=\d+$','version/code=136',e,count=1)
e,n2=re.subn(r'(?m)^version/name="[^"]*"$','version/name="0.21.0D2D.63"',e,count=1)
if n1!=1 or n2!=1:
    raise SystemExit("D2D.63 version anchors missing")
ep.write_text(e,encoding="utf-8")

sm=root/"scripts/save/save_manager.gd"
if sm.exists():
    t=sm.read_text(encoding="utf-8")
    t=re.sub(r'const GAME_VERSION := "[^"]+"',
             'const GAME_VERSION := "0.21.0D2D.63"',t,count=1)
    sm.write_text(t,encoding="utf-8")

print("Applied D2D.63 HEAD ONLY: exact user-provided female head; every body/gear proportion unchanged from D2D.62.")
